def apply_profile():
    from . import db
    db.init()
    with db.connect(True) as c:
        c.executemany('INSERT INTO settings(key,value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value', PROFILE.items())


def documents(s):
    """Render terms from the same tariff settings used by checkout."""
    from .db import money
    seller = s.get('legal_name') or '[Наименование продавца не заполнено]'
    details = s.get('legal_details') or '[Реквизиты продавца не заполнены]'
    email = s.get('legal_email') or '[Email для обращений не заполнен]'
    address = s.get('legal_address') or '[Адрес для юридически значимых обращений не заполнен]'
    identity = f'{seller}\n{details}\nАдрес для обращений: {address}\nТелефон: {s["phone"]}. Email: {email}.'
    delivery = f'''Доставка и самовывоз
Пункт самовывоза: {s['address']}. Режим работы: {s['hours']}.
{s.get('delivery_area', '')}
Стоимость доставки: {money(s['delivery_fee'],s['currency'])}. '''
    if int(s['free_delivery_from']) > 0:
        delivery += f"При сумме блюд от {money(s['free_delivery_from'],s['currency'])} доставка в основной зоне бесплатна. "
    delivery += f'''За пределами указанной зоны заказ оформляется по телефону: возможность, стоимость и срок доставки согласовываются до подтверждения и оплаты. Дополнительные услуги без согласия покупателя не включаются.
Ориентировочное время приготовления и доставки после подтверждения: {s.get('delivery_time') or 'уточняется при заказе'}. Дорожная ситуация может повлиять на срок; согласованное время сообщается при подтверждении. При задержке магазин связывается с покупателем. Это условие не ограничивает права покупателя при нарушении согласованного срока.
При самовывозе скидка {s.get('pickup_discount','0')}% на блюда. Скидка рассчитывается для каждой единицы товара с округлением до копейки; итог виден до подтверждения заказа.
Минимальная сумма блюд до скидки: {money(s['minimum_order'],s['currency'])}.'''
    payment = '''Оплата
Наличными при получении. '''
    if s.get('card_on_receipt') == '1':
        payment += 'Банковской картой курьеру или в пункте самовывоза при получении. '
    payment += '''Онлайн-оплата картой и СБП предлагается после подключения эквайринга; доступные варианты отображаются в форме заказа и на защищённой странице банка. Реквизиты карты магазин не получает. До подтверждения покупатель видит стоимость блюд, скидку, доставку и общую сумму. Кассовый чек выдаётся или направляется в установленном законом порядке.'''
    returns = f'''Отмена заказа, качество и возврат
Для изменения или отмены заказа свяжитесь с магазином: {s['phone']}, {email}. При отказе от услуги покупатель оплачивает только документально подтверждённые фактически понесённые расходы, связанные с исполнением заказа, в случаях, предусмотренных законом. Фиксированный штраф или автоматическое удержание всей суммы не применяется.
При недостаче, недостатках качества или нарушении срока сообщите номер заказа и описание проблемы. Фото поможет рассмотрению, но не является обязательным условием принятия претензии. Отсутствие кассового чека само по себе не лишает права обратиться с требованием.
Требования о недостатках, уменьшении цены, возврате денег и возмещении убытков рассматриваются в порядке и сроки, установленные Законом РФ «О защите прав потребителей». Деньги за онлайн-платёж возвращаются через платёжного провайдера после согласования основания возврата. Обращение к продавцу не ограничивает право обратиться в Роспотребнадзор или суд.'''
    offer = f'''Условия заказа и публичная оферта
Редакция от 27 сентября 2026 года

1. Продавец и предмет договора
{identity}
Продавец предлагает приготовление и продажу блюд для личного потребления, самовывоз и доставку на условиях сайта. Применяются ГК РФ, Закон РФ от 07.02.1992 № 2300-1 и Правила оказания услуг общественного питания, утверждённые постановлением Правительства РФ от 21.09.2020 № 1515; для сопутствующих товаров — применимые правила розничной продажи.

2. Оформление и подтверждение
Регистрация и личный кабинет для заказа на сайте не требуются. Покупатель выбирает блюда, способ получения и оплаты, указывает контактные данные и адрес доставки, проверяет итог и нажимает «Подтвердить заказ». Это подтверждение покупателем состава и стоимости заказа и принятие условий. После сохранения заказа сайт показывает номер и ссылку на его статус.
Приготовление и доставка начинаются только после подтверждения покупателем на сайте, в Telegram, по телефону или в чате и принятия заказа магазином. Для онлайн-оплаты дополнительно требуется подтверждение платежа банком. Сотрудник уточняет возможность доставки по адресу и время получения. Изменения состава, цены и дополнительных услуг требуют согласования с покупателем. При невозможности исполнения оплаченного заказа магазин согласовывает замену либо возврат.

3. {delivery}

4. {payment}

5. Информация о блюдах
Название, состав, цена, вес и доступные сведения о пищевой ценности указаны в карточках. При пищевой аллергии уточните возможность перекрёстного контакта до заказа. Срок годности, условия хранения и сведения об изготовлении сообщаются на маркировке и в сопровождающей информации. Изображение показывает вариант подачи и не изменяет согласованный состав и массу.

6. {returns}

7. Персональные данные и изменения условий
Обработка данных для заключения и исполнения заказа описана в отдельной политике конфиденциальности. Принятие этих условий не означает согласия на рекламную рассылку. Новая редакция условий применяется к новым заказам; для уже оформленного заказа сохраняются подтверждённые условия.'''
    privacy = f'''Политика обработки персональных данных
Редакция от 27 сентября 2026 года

1. Оператор
{identity}

2. Данные и цели
Для оформления, исполнения, оплаты и поддержки заказа обрабатываются имя, телефон, адрес доставки, состав и стоимость заказа, способ оплаты, комментарий и статусы. Не указывайте в комментарии диагнозы и другие чувствительные сведения. При заказе в чате Telegram или MAX обрабатываются также идентификаторы пользователя и чата соответствующего мессенджера. Регистрация личного кабинета на сайте не предусмотрена. По желанию покупателя личный кабинет подключается в Telegram или MAX после подтверждения собственного номера через кнопку передачи контакта. Для сопоставления заказов, показа истории и отправки статусов сохраняются подтверждённый номер, идентификаторы пользователя и чата, время подтверждения и настройка уведомлений. Введённый вручную номер не даёт доступа к истории. Команда /stopupdates отключает уведомления кабинета, /logout удаляет его привязку, сохраняя сами заказы. Сообщения о заказах не удаляются ботом при навигации.
Для работы корзины и защиты сайта используются необходимые cookies сессии, случайный идентификатор посетителя и технические сведения о запросах. Отключение cookies может нарушить работу корзины. Для анализа источников заказов магазин сохраняет переданные в ссылке UTM-метки: источник, канал, кампанию, объявление и ключевое слово. Привязка переходов к текущему браузеру хранится до 90 дней, а источник оформленного заказа — вместе с заказом. Если магазин включил Яндекс Метрику, её код загружается только после вашего разрешения. Передаются сведения о посещениях, действиях с товарами и покупках; имя, телефон, адрес доставки и приватная ссылка заказа в события не включаются. Изменить решение можно кнопкой «Настройки аналитики» в подвале витрины. Отказ от Метрики не мешает оформлению заказа.

3. Основания и действия
Обработка необходимых для заказа данных основана на заключении и исполнении договора по инициативе покупателя (п. 5 ч. 1 ст. 6 Федерального закона № 152-ФЗ), а обязательное хранение расчётных документов — на требованиях закона. Осуществляются сбор, запись, систематизация, хранение, уточнение, использование, передача в необходимом объёме, удаление и уничтожение с использованием средств автоматизации и без них. Принятие оферты не является согласием на рекламу; рекламные рассылки этим сайтом не осуществляются.

4. Доступ и передача
Доступ предоставляется уполномоченным сотрудникам. Данные в необходимом для заказа объёме могут получать курьеры, обслуживающий хостинг, система учёта iiko и подключённый платёжный провайдер. Номера карт и коды безопасности вводятся на странице банка и магазином не хранятся. Перечень привлечённых оператором исполнителей и условия обработки можно уточнить по указанным контактам. Публикация данных в открытом доступе не производится.

5. Хранение и защита
Данные хранятся не дольше, чем требуется для целей обработки и обязательных сроков хранения по закону. После достижения целей данные удаляются или обезличиваются, если закон не требует дальнейшего хранения. Оператор ограничивает доступ к данным, использует защищённое соединение и резервное копирование; удаление учитывается при восстановлении из резервной копии.

6. Права и обращения
Покупатель вправе запросить сведения об обработке, уточнение, блокирование или удаление данных при наличии предусмотренных законом оснований. Обращения направляются по контактам оператора; оператор может запросить сведения, необходимые для идентификации заявителя. Если обработка отдельно основана на согласии, его можно отозвать; это не прекращает обработку, необходимую по договору или закону. Ответ предоставляется в сроки, установленные № 152-ФЗ. Действия оператора можно обжаловать в Роскомнадзор или суд.'''
    return {'offer': s.get('offer_text') or offer, 'privacy': s.get('privacy_text') or privacy,
            'delivery': delivery + '\n\n' + payment, 'returns': returns,
            'contacts': identity + f"\nСамовывоз: {s['address']}\n{s['hours']}"}


def snapshot(s):
    text = json.dumps(documents(s), ensure_ascii=False, sort_keys=True)
    return text, hashlib.sha256(text.encode()).hexdigest()
